const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'JavaScript Rising Stars';
pres.title = '2024 JavaScript Rising Stars';

// Color palette - Midnight Executive with JS accent
const colors = {
  darkBg: "0F172A",      // Slate 900
  lightBg: "F8FAFC",     // Slate 50
  accent: "14B8A6",       // Teal 500
  accentDark: "0D9488",  // Teal 600
  highlight: "F7DF1E",   // JS Yellow
  text: "1E293B",        // Slate 800
  textMuted: "64748B",    // Slate 500
  white: "FFFFFF",
  chartColors: ["14B8A6", "3B82F6", "8B5CF6", "F59E0B", "EF4444", "10B981", "6366F1", "EC4899", "84CC16", "06B6D4"]
};

// Helper for shadow (fresh object each time)
const makeShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1 });

// ============ SLIDE 1: Title Cover ============
let slide1 = pres.addSlide();
slide1.background = { color: colors.darkBg };

// Accent shape - top bar
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.15, fill: { color: colors.accent }
});

// Year badge
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.2, w: 1.2, h: 0.5, fill: { color: colors.accent }
});
slide1.addText("2024", {
  x: 0.5, y: 1.2, w: 1.2, h: 0.5, fontSize: 20, bold: true, color: colors.darkBg, align: "center", valign: "middle"
});

// Main title
slide1.addText("JavaScript Rising Stars", {
  x: 0.5, y: 1.9, w: 9, h: 0.9, fontSize: 44, bold: true, color: colors.white, margin: 0
});

// Subtitle
slide1.addText("Top Projects and Ecosystem Shifts", {
  x: 0.5, y: 2.75, w: 9, h: 0.6, fontSize: 24, color: colors.accent, margin: 0
});

// Methodology note
slide1.addText("Based on GitHub stars added in 2024 | 9th Annual Edition | Source: risingstars.js.org", {
  x: 0.5, y: 3.5, w: 9, h: 0.4, fontSize: 12, color: colors.textMuted, margin: 0
});

// Decorative element - bottom accent
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.2, w: 3, h: 0.08, fill: { color: colors.accent }
});

// Audience tag
slide1.addText("For Frontend Engineers & Engineering Managers", {
  x: 0.5, y: 4.8, w: 6, h: 0.3, fontSize: 11, color: colors.textMuted, margin: 0
});

// ============ SLIDE 2: Overall Top 10 ============
let slide2 = pres.addSlide();
slide2.background = { color: colors.lightBg };

// Title
slide2.addText("Top 10 Most-Starred Projects", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, fontSize: 32, bold: true, color: colors.text, margin: 0
});
slide2.addText("shadcn/ui dominates with +38k stars in 2024", {
  x: 0.5, y: 0.85, w: 9, h: 0.35, fontSize: 14, color: colors.textMuted, margin: 0
});

// Horizontal bar chart data
const top10Data = [
  { name: "shadcn/ui", stars: 38.0 },
  { name: "Excalidraw", stars: 27.0 },
  { name: "AFFiNE", stars: 19.6 },
  { name: "Bruno", stars: 18.7 },
  { name: "n8n", stars: 17.0 },
  { name: "htmx", stars: 16.8 },
  { name: "Tauri", stars: 15.9 },
  { name: "Supabase", stars: 14.5 },
  { name: "Flowise", stars: 14.5 },
  { name: "Payload", stars: 14.4 }
];

slide2.addChart(pres.charts.BAR, [{
  name: "Stars Added (k)",
  labels: top10Data.map(d => d.name),
  values: top10Data.map(d => d.stars)
}], {
  x: 0.5, y: 1.3, w: 9, h: 4,
  barDir: "bar",
  chartColors: [colors.accent],
  chartArea: { fill: { color: colors.lightBg } },
  catAxisLabelColor: colors.text,
  catAxisLabelFontSize: 11,
  catAxisLabelFontBold: false,
  valAxisLabelColor: colors.textMuted,
  valAxisLabelFontSize: 10,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: colors.text,
  dataLabelFontSize: 10,
  showLegend: false,
  valAxisMaxVal: 42
});

// Source citation
slide2.addText("Source: risingstars.js.org/2024 | Stars added in 2024", {
  x: 0.5, y: 5.35, w: 6, h: 0.25, fontSize: 9, color: colors.textMuted, margin: 0
});

// ============ SLIDE 3: shadcn/ui Deep Dive ============
let slide3 = pres.addSlide();
slide3.background = { color: colors.lightBg };

// Left accent bar
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: colors.accent }
});

// Title badge
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 0.3, w: 2.2, h: 0.45, fill: { color: colors.accent }
});
slide3.addText("CHAMPION 2024", {
  x: 0.5, y: 0.3, w: 2.2, h: 0.45, fontSize: 12, bold: true, color: colors.white, align: "center", valign: "middle"
