  x: 0.5, y: 0.85, w: 5, h: 0.6, fontSize: 28, bold: true, color: colors.text, margin: 0
});

// Stats cards - left column
const statsData = [
  { value: "77.5k", label: "Total Stars", sub: "since Jan 2023" },
  { value: "38.0k", label: "Added in 2024", sub: "vs 39.5k in 2023" },
  { value: "#1", label: "Overall Rank", sub: "2nd consecutive year" }
];

statsData.forEach((stat, i) => {
  const y = 1.6 + i * 1.15;
  // Card background
  slide3.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: y, w: 3.2, h: 1.0, fill: { color: colors.white }, shadow: makeShadow()
  });
  // Value
  slide3.addText(stat.value, {
    x: 0.7, y: y + 0.1, w: 2.8, h: 0.5, fontSize: 28, bold: true, color: colors.accent, margin: 0
  });
  // Label
  slide3.addText(stat.label, {
    x: 0.7, y: y + 0.55, w: 2.8, h: 0.25, fontSize: 12, bold: true, color: colors.text, margin: 0
  });
  // Sub
  slide3.addText(stat.sub, {
    x: 0.7, y: y + 0.75, w: 2.8, h: 0.2, fontSize: 9, color: colors.textMuted, margin: 0
  });
});

// Right side - Key features
slide3.addText("Key 2024 Additions", {
  x: 4.0, y: 1.6, w: 5.5, h: 0.4, fontSize: 16, bold: true, color: colors.text, margin: 0
});

const features = [
  "Charts (powered by Recharts)",
  "Themes (CSS variable generation)",
  "Blocks (layout collections for web apps)",
  "Responsive sidebar component",
  "CLI with multi-framework support: Next.js, Remix, Vite, Laravel, monorepos"
];

slide3.addText(
  features.map((f, i) => ({ text: f, options: { bullet: true, breakLine: i < features.length - 1 } })),
  { x: 4.0, y: 2.05, w: 5.5, h: 2.0, fontSize: 13, color: colors.text, paraSpaceAfter: 6 }
);

// Ecosystem note
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 4.0, y: 4.2, w: 5.5, h: 0.7, fill: { color: "F0FDFA" }
});
slide3.addText("Spawned ecosystem derivatives: Motion-Primitives, Magic UI + integration with Vercel's v0 for AI-generated components", {
  x: 4.15, y: 4.3, w: 5.2, h: 0.5, fontSize: 10, color: colors.accentDark, margin: 0
});

// ============ SLIDE 4: Frontend Frameworks ============
let slide4 = pres.addSlide();
slide4.background = { color: colors.lightBg };

// Title
slide4.addText("Frontend Frameworks Shakeup", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, fontSize: 32, bold: true, color: colors.text, margin: 0
});
slide4.addText("htmx overtakes React as #1 by stars added", {
  x: 0.5, y: 0.85, w: 9, h: 0.35, fontSize: 14, color: colors.textMuted, margin: 0
});

// Bar chart - comparing frameworks
const frameworkData = [
  { name: "htmx", stars: 16.8 },
  { name: "React", stars: 14.2 },
  { name: "Svelte", stars: 6.1 },
  { name: "Vue.js", stars: 5.9 },
  { name: "Angular", stars: 3.5 }
];

slide4.addChart(pres.charts.BAR, [{
  name: "Stars Added (k)",
  labels: frameworkData.map(d => d.name),
  values: frameworkData.map(d => d.stars)
}], {
  x: 0.5, y: 1.3, w: 5.5, h: 3.5,
  barDir: "col",
  chartColors: [colors.accent],
  chartArea: { fill: { color: colors.lightBg } },
  catAxisLabelColor: colors.text,
  catAxisLabelFontSize: 12,
  valAxisLabelColor: colors.textMuted,
  valAxisLabelFontSize: 10,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: colors.text,
  dataLabelFontSize: 11,
  showLegend: false,
  valAxisMaxVal: 20
});

// Right side - insights
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.3, w: 3.2, h: 1.6, fill: { color: colors.white }, shadow: makeShadow()
});
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.3, w: 3.2, h: 0.08, fill: { color: colors.accent }
});
slide4.addText("htmx Philosophy", {
  x: 6.5, y: 1.45, w: 2.8, h: 0.3, fontSize: 12, bold: true, color: colors.text, margin: 0
});
slide4.addText("Extends HTML with hx-* attributes for AJAX, WebSockets, server-driven interactivity without JavaScript", {
  x: 6.5, y: 1.75, w: 2.8, h: 0.9, fontSize: 10, color: colors.textMuted, margin: 0
});

slide4.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 3.1, w: 3.2, h: 1.6, fill: { color: colors.white }, shadow: makeShadow()
});
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 3.1, w: 3.2, h: 0.08, fill: { color: "3B82F6" }
});
slide4.addText("React 19 Release", {
  x: 6.5, y: 3.25, w: 2.8, h: 0.3, fontSize: 12, bold: true, color: colors.text, margin: 0
});
slide4.addText("Server Components, Server Functions, Custom Elements, new hooks, form actions — React evolving toward \"specification for frameworks\"", {
  x: 6.5, y: 3.55, w: 2.8, h: 0.95, fontSize: 10, color: colors.textMuted, margin: 0
});

// Svelte 5 note
slide4.addText("Svelte 5 introduced \"runes\" — explicit reactive state mechanism. Holds highest positive opinion in State of JS survey.", {
  x: 0.5, y: 5.0, w: 9, h: 0.3, fontSize: 10, color: colors.textMuted, margin: 0
});

// ============ SLIDE 5: React Ecosystem ============
let slide5 = pres.addSlide();
slide5.background = { color: colors.lightBg };

// Header bar
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9, fill: { color: "61DAFB" }  // React blue
});
slide5.addText("React Ecosystem", {
  x: 0.5, y: 0.2, w: 5, h: 0.5, fontSize: 28, bold: true, color: colors.white, margin: 0
});
slide5.addText("Top 5 by GitHub Stars Added in 2024", {
  x: 0.5, y: 0.55, w: 5, h: 0.3, fontSize: 12, color: "1E3A5F", margin: 0
});

// React top 5 cards
const reactEcosystem = [
  { rank: "#1", name: "shadcn/ui", stars: "+38.0k", color: colors.accent },
  { rank: "#2", name: "Excalidraw", stars: "+27.0k", color: "10B981" },
  { rank: "#3", name: "Payload", stars: "+14.4k", color: "6366F1" },
  { rank: "#4", name: "Magic UI", stars: "+13.2k", color: "F59E0B" },
  { rank: "#5", name: "Next.js", stars: "+12.1k", color: colors.text }
];

reactEcosystem.forEach((item, i) => {
  const x = 0.5 + i * 1.85;
  // Card
  slide5.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.2, w: 1.7, h: 2.2, fill: { color: colors.white }, shadow: makeShadow()
  });
  // Rank badge
  slide5.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.2, w: 1.7, h: 0.4, fill: { color: item.color }
  });
  slide5.addText(item.rank, {
    x: x, y: 1.2, w: 1.7, h: 0.4, fontSize: 14, bold: true, color: colors.white, align: "center", valign: "middle"
  });
  // Project name
  slide5.addText(item.name, {
    x: x + 0.1, y: 1.7, w: 1.5, h: 0.5, fontSize: 13, bold: true, color: colors.text, align: "center", margin: 0
  });
  // Stars
  slide5.addText(item.stars, {
    x: x + 0.1, y: 2.2, w: 1.5, h: 0.4, fontSize: 18, bold: true, color: item.color, align: "center", margin: 0
  });
  slide5.addText("stars added", {
    x: x + 0.1, y: 2.55, w: 1.5, h: 0.25, fontSize: 9, color: colors.textMuted, align: "center", margin: 0
  });
});

// Key insight
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.65, w: 9, h: 1.5, fill: { color: "F0F9FF" }
});
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.65, w: 0.1, h: 1.5, fill: { color: "61DAFB" }
});
slide5.addText("React's Evolution: From Library to Framework Specification", {
  x: 0.8, y: 3.8, w: 8.5, h: 0.35, fontSize: 14, bold: true, color: colors.text, margin: 0
});
slide5.addText("With React 19's Server Components and Server Functions, multiple frameworks (Next.js, Remix, etc.) now interpret React's primitives differently. As Robin Wieruch noted, React is evolving from a library into \"a specification for frameworks\" — a shift toward framework-first mindset while still allowing client-only usage.", {
  x: 0.8, y: 4.15, w: 8.5, h: 0.9, fontSize: 11, color: colors.textMuted, margin: 0
});

// ============ SLIDE 6: Vue Ecosystem ============
let slide6 = pres.addSlide();
slide6.background = { color: colors.lightBg };

// Header bar - Vue green
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9, fill: { color: "42B883" }  // Vue green
});
slide6.addText("Vue Ecosystem", {
  x: 0.5, y: 0.2, w: 5, h: 0.5, fontSize: 28, bold: true, color: colors.white, margin: 0
});
slide6.addText("Top 5 by GitHub Stars Added in 2024", {
  x: 0.5, y: 0.55, w: 5, h: 0.3, fontSize: 12, color: "1E3A5F", margin: 0
});

// Vue top 5 cards
const vueEcosystem = [
  { rank: "#1", name: "Nuxt", stars: "+6.2k", color: "42B883" },
  { rank: "#2", name: "PrimeVue", stars: "+5.4k", color: "42B883" },
  { rank: "#3", name: "Slidev", stars: "+4.7k", color: "42B883" },
  { rank: "#4", name: "shadcn-vue", stars: "+4.1k", color: "42B883" },
  { rank: "#5", name: "VitePress", stars: "+3.7k", color: "42B883" }
];

vueEcosystem.forEach((item, i) => {
  const x = 0.5 + i * 1.85;
  slide6.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.2, w: 1.7, h: 2.2, fill: { color: colors.white }, shadow: makeShadow()
  });
  slide6.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.2, w: 1.7, h: 0.4, fill: { color: item.color }
  });
  slide6.addText(item.rank, {
    x: x, y: 1.2, w: 1.7, h: 0.4, fontSize: 14, bold: true, color: colors.white, align: "center", valign: "middle"
  });
  slide6.addText(item.name, {
    x: x + 0.1, y: 1.7, w: 1.5, h: 0.5, fontSize: 13, bold: true, color: colors.text, align: "center", margin: 0
  });
  slide6.addText(item.stars, {
    x: x + 0.1, y: 2.2, w: 1.5, h: 0.4, fontSize: 18, bold: true, color: item.color, align: "center", margin: 0
  });
  slide6.addText("stars added", {
    x: x + 0.1, y: 2.55, w: 1.5, h: 0.25, fontSize: 9, color: colors.textMuted, align: "center", margin: 0
  });
});

// Key insight
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.65, w: 9, h: 1.5, fill: { color: "F0FDF4" }
});
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.65, w: 0.1, h: 1.5, fill: { color: "42B883" }
});
slide6.addText("Vue 3.5 Reactivity Overhaul & Ecosystem Maturity", {
  x: 0.8, y: 3.8, w: 8.5, h: 0.35, fontSize: 14, bold: true, color: colors.text, margin: 0
});
slide6.addText("Vue 3.5 reworked its reactivity system with the lighter alien-signals approach landing in main branch. Daniel Roe (Nuxt core team lead) highlighted the active release cycle and regular performance improvements. Flourishing of Vue UI libraries (PrimeVue, shadcn-vue) signals growing ecosystem confidence.", {
  x: 0.8, y: 4.15, w: 8.5, h: 0.9, fontSize: 11, color: colors.textMuted, margin: 0
});

// ============ SLIDE 7: Emerging Themes ============
let slide7 = pres.addSlide();
slide7.background = { color: colors.lightBg };

// Title
slide7.addText("Emerging Themes in 2024", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, fontSize: 32, bold: true, color: colors.text, margin: 0
});
slide7.addText("AI Tools, Desktop Apps, and Browser Innovation", {
  x: 0.5, y: 0.85, w: 9, h: 0.35, fontSize: 14, color: colors.textMuted, margin: 0
});

// Three theme cards
const themes = [
  {
    title: "AI-Powered Projects",
    color: "8B5CF6",
    projects: [
      { name: "n8n", stat: "+17.0k", desc: "Workflow automation with native AI" },
      { name: "Flowise", stat: "+14.5k", desc: "Drag & drop UI for custom LLM flows" },
      { name: "AFFiNE", stat: "+19.6k", desc: "Knowledge base with AI capabilities" }
    ]
  },
  {
    title: "Desktop & Mobile",
    color: "0284C7",
    projects: [
      { name: "Tauri", stat: "+15.9k", desc: "Lighter desktop/mobile apps with web tech" }
    ]
  },
  {
    title: "Browser Innovation",
    color: "059669",
    projects: [
      { name: "PGlite", stat: "New", desc: "Postgres via WebAssembly" },
      { name: "WebVM", stat: "New", desc: "Virtual machine running in browser" },
      { name: "Supabase", stat: "+14.5k", desc: "Open-source Firebase alternative" }
    ]
  }
];

themes.forEach((theme, i) => {
  const x = 0.5 + i * 3.1;
  // Card background
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.35, w: 2.9, h: 3.6, fill: { color: colors.white }, shadow: makeShadow()
  });
  // Top accent
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.35, w: 2.9, h: 0.08, fill: { color: theme.color }
  });
  // Title
  slide7.addText(theme.title, {
    x: x + 0.15, y: 1.5, w: 2.6, h: 0.4, fontSize: 14, bold: true, color: colors.text, margin: 0
  });

  // Projects
  theme.projects.forEach((proj, j) => {
    const y = 2.0 + j * 0.95;
    slide7.addText(proj.name, {
      x: x + 0.15, y: y, w: 2.0, h: 0.3, fontSize: 13, bold: true, color: theme.color, margin: 0
    });
    slide7.addText(proj.stat, {
      x: x + 2.0, y: y, w: 0.75, h: 0.3, fontSize: 11, bold: true, color: colors.text, align: "right", margin: 0
    });
    slide7.addText(proj.desc, {
      x: x + 0.15, y: y + 0.3, w: 2.6, h: 0.4, fontSize: 9, color: colors.textMuted, margin: 0
    });
  });
});

// Key stat highlight
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 5.1, w: 9, h: 0.4, fill: { color: "F5F3FF" }
});
slide7.addText("4 of top 10 overall projects have significant AI capabilities or integrations", {
  x: 0.7, y: 5.1, w: 8.6, h: 0.4, fontSize: 11, color: "7C3AED", valign: "middle", margin: 0
});

// ============ SLIDE 8: Key Takeaways ============
let slide8 = pres.addSlide();
slide8.background = { color: colors.darkBg };

// Top accent
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.1, fill: { color: colors.accent }
});

// Title
slide8.addText("Key Takeaways", {
  x: 0.5, y: 0.35, w: 9, h: 0.6, fontSize: 32, bold: true, color: colors.white, margin: 0
});
slide8.addText("What 2024 Tells Us About JavaScript's Future", {
  x: 0.5, y: 0.9, w: 9, h: 0.35, fontSize: 14, color: colors.accent, margin: 0
});

// Takeaway cards
const takeaways = [
  { num: "1", title: "Component Ownership Beats Imports", desc: "shadcn/ui's model of letting developers own and customize component code proved its staying power for a second year" },
  { num: "2", title: "HTML-First Is Serious", desc: "htmx overtook React as the #1 front-end framework by stars added, validating server-driven, low-JavaScript architectures" },
  { num: "3", title: "React Is Becoming a Framework Spec", desc: "With Server Components and Server Functions in React 19, multiple frameworks now interpret React's primitives differently" },
  { num: "4", title: "AI Integration Is Table Stakes", desc: "Four of the top 10 overall projects have significant AI capabilities — this is now an expectation, not a differentiator" },
  { num: "5", title: "Vue's UI Library Ecosystem Signals Maturity", desc: "High-quality UI libraries and Vue 3.5's reactivity overhaul demonstrate a confident, maturing ecosystem" }
];

takeaways.forEach((item, i) => {
  const y = 1.4 + i * 0.78;
  // Number circle
  slide8.addShape(pres.shapes.OVAL, {
    x: 0.5, y: y, w: 0.4, h: 0.4, fill: { color: colors.accent }
  });
  slide8.addText(item.num, {
    x: 0.5, y: y, w: 0.4, h: 0.4, fontSize: 14, bold: true, color: colors.darkBg, align: "center", valign: "middle"
  });
  // Title
  slide8.addText(item.title, {
    x: 1.05, y: y - 0.02, w: 8.4, h: 0.35, fontSize: 14, bold: true, color: colors.white, margin: 0
  });
  // Description
  slide8.addText(item.desc, {
    x: 1.05, y: y + 0.32, w: 8.4, h: 0.4, fontSize: 11, color: colors.textMuted, margin: 0
  });
});

// Forward-looking footer
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.2, w: 10, h: 0.425, fill: { color: colors.accent }
});
slide8.addText("Looking Ahead to 2025: Component ownership, HTML-first approaches, and AI integration are the defining trends.", {
  x: 0.5, y: 5.25, w: 9, h: 0.35, fontSize: 12, bold: true, color: colors.darkBg, valign: "middle", margin: 0
});

// Save
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Presentation saved to /app/output/final_deck.pptx"))
  .catch(err => console.error("Error:", err));

